// wf_nutrir_o_crear_deal_periodo.js
// WF: "Mora 2 — Nutrir o Crear Deal Período"
// Trigger: Ticket en pipeline 3353793749, etapa Cerrado (4594251972),
//          resultado_del_caso = "Resuelto con pago total FINAER" o "Resuelto con pago parcial FINAER"
//          + nro_expediente conocido + periodo_de_deuda conocido
//
// Lógica:
//   ¿Existe deal en pipeline 3403406575 con mismo nro_expediente y periodo_de_deuda?
//   → SÍ: suma conceptos del ticket al deal existente + nota
//   → NO: crea deal de período + asocia al ticket + busca/crea deal maestro (3920555199) + asocia

const hubspot = require('@hubspot/api-client');

exports.main = async (event, callback) => {
  const hubspotClient = new hubspot.Client({
    accessToken: process.env.token
  });

  const ticketId = String(event.object.objectId);

  // ── Leer inputs del ticket ──────────────────────────────────────────────
  const nroExpediente     = event.inputFields['nro_expediente'];
  const periodoDeDeuda    = event.inputFields['periodo_de_deuda'];
  const nombreInquilino   = event.inputFields['nombre_y_apellido_del_inquilino'] || '';

  // Conceptos de deuda (ticket → deal: alquiler/luz/gas/abl tienen nombres distintos)
  const tAlquiler = parseFloat(event.inputFields['deuda_alquiler']              || 0);
  const tExpensas = parseFloat(event.inputFields['deuda_expensas']              || 0);
  const tLuz      = parseFloat(event.inputFields['deuda_luz']                   || 0);
  const tGas      = parseFloat(event.inputFields['deuda_gas']                   || 0);
  const tAbl      = parseFloat(event.inputFields['deuda_abl']                   || 0);
  const tAysa     = parseFloat(event.inputFields['deuda_aysa']                  || 0);
  const tLlaves   = parseFloat(event.inputFields['deuda_por_entrega_de_llaves'] || 0);

  if (!nroExpediente || !periodoDeDeuda) {
    return callback({ outputFields: { resultado: 'OMITIDO: falta nro_expediente o periodo_de_deuda' } });
  }

  const totalTicket = tAlquiler + tExpensas + tLuz + tGas + tAbl + tAysa + tLlaves;
  const ahora = new Date().toLocaleString('es-AR', { timeZone: 'America/Buenos_Aires' });

  // ── 1. Buscar deal de período existente ────────────────────────────────
  const searchPeriodo = await hubspotClient.crm.deals.searchApi.doSearch({
    filterGroups: [{
      filters: [
        { propertyName: 'pipeline',        operator: 'EQ', value: '3403406575' },
        { propertyName: 'nro_expediente',  operator: 'EQ', value: String(nroExpediente) },
        { propertyName: 'periodo_de_deuda', operator: 'EQ', value: periodoDeDeuda }
      ]
    }],
    properties: [
      'dealname', 'alquiler', 'deuda_expensas', 'luz', 'gas', 'abl',
      'deuda_aysa', 'deuda_por_entrega_de_llaves', 'monto_total_de_la_deuda_acumulada'
    ],
    limit: 1
  });

  // ── CASO SÍ: nutrir deal existente ────────────────────────────────────
  if (searchPeriodo.results.length > 0) {
    const deal   = searchPeriodo.results[0];
    const dealId = deal.id;
    const p      = deal.properties;

    const nuevoAlquiler = parseFloat(p.alquiler                       || 0) + tAlquiler;
    const nuevoExpensas = parseFloat(p.deuda_expensas                 || 0) + tExpensas;
    const nuevoLuz      = parseFloat(p.luz                            || 0) + tLuz;
    const nuevoGas      = parseFloat(p.gas                            || 0) + tGas;
    const nuevoAbl      = parseFloat(p.abl                            || 0) + tAbl;
    const nuevoAysa     = parseFloat(p.deuda_aysa                     || 0) + tAysa;
    const nuevoLlaves   = parseFloat(p.deuda_por_entrega_de_llaves    || 0) + tLlaves;
    const nuevoTotal    = nuevoAlquiler + nuevoExpensas + nuevoLuz + nuevoGas + nuevoAbl + nuevoAysa + nuevoLlaves;

    await hubspotClient.crm.deals.basicApi.update(dealId, {
      properties: {
        alquiler:                        String(nuevoAlquiler),
        deuda_expensas:                  String(nuevoExpensas),
        luz:                             String(nuevoLuz),
        gas:                             String(nuevoGas),
        abl:                             String(nuevoAbl),
        deuda_aysa:                      String(nuevoAysa),
        deuda_por_entrega_de_llaves:     String(nuevoLlaves),
        monto_total_de_la_deuda_acumulada: String(nuevoTotal)
      }
    });

    const nota =
      `[${ahora}] Concepto sumado desde ticket #${ticketId}\n` +
      `  Alquiler:  $${fmt(tAlquiler)}\n` +
      `  Expensas:  $${fmt(tExpensas)}\n` +
      `  Luz:       $${fmt(tLuz)}\n` +
      `  Gas:       $${fmt(tGas)}\n` +
      `  ABL:       $${fmt(tAbl)}\n` +
      `  AYSA:      $${fmt(tAysa)}\n` +
      `  Llaves:    $${fmt(tLlaves)}\n` +
      `  ─────────────────────────────\n` +
      `  Total acumulado del período: $${fmt(nuevoTotal)}\n` +
      `  Período: ${periodoDeDeuda}`;

    await crearNota(hubspotClient, nota, dealId, 214);

    return callback({ outputFields: { resultado: `NUTRIDO — deal ${dealId} | total período: $${fmt(nuevoTotal)}` } });
  }

  // ── CASO NO: crear deal de período nuevo ──────────────────────────────
  const dealNombre = [nroExpediente, nombreInquilino, periodoDeDeuda]
    .filter(Boolean).join(' — ');

  const nuevoPeriodo = await hubspotClient.crm.deals.basicApi.create({
    properties: {
      dealname:                          dealNombre,
      pipeline:                          '3403406575',
      dealstage:                         '4660102351',   // En recupero
      nro_expediente:                    String(nroExpediente),
      periodo_de_deuda:                  periodoDeDeuda,
      alquiler:                          String(tAlquiler),
      deuda_expensas:                    String(tExpensas),
      luz:                               String(tLuz),
      gas:                               String(tGas),
      abl:                               String(tAbl),
      deuda_aysa:                        String(tAysa),
      deuda_por_entrega_de_llaves:       String(tLlaves),
      monto_total_de_la_deuda_acumulada: String(totalTicket)
    }
  });

  const dealPeriodoId = nuevoPeriodo.id;

  // Asociar deal de período → ticket
  await hubspotClient.crm.associations.v4.basicApi.create(
    'deals', dealPeriodoId, 'tickets', ticketId,
    [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 28 }]
  );

  const notaNuevo =
    `[${ahora}] Deal de período creado desde ticket #${ticketId}\n` +
    `  Alquiler:  $${fmt(tAlquiler)}\n` +
    `  Expensas:  $${fmt(tExpensas)}\n` +
    `  Luz:       $${fmt(tLuz)}\n` +
    `  Gas:       $${fmt(tGas)}\n` +
    `  ABL:       $${fmt(tAbl)}\n` +
    `  AYSA:      $${fmt(tAysa)}\n` +
    `  Llaves:    $${fmt(tLlaves)}\n` +
    `  ─────────────────────────────\n` +
    `  Total del período: $${fmt(totalTicket)}\n` +
    `  Período: ${periodoDeDeuda}`;

  await crearNota(hubspotClient, notaNuevo, dealPeriodoId, 214);

  // ── Buscar o crear deal MAESTRO ───────────────────────────────────────
  const searchMaestro = await hubspotClient.crm.deals.searchApi.doSearch({
    filterGroups: [{
      filters: [
        { propertyName: 'pipeline',       operator: 'EQ', value: '3920555199' },
        { propertyName: 'nro_expediente', operator: 'EQ', value: String(nroExpediente) }
      ]
    }],
    properties: ['dealname', 'nro_expediente'],
    limit: 1
  });

  let dealMaestroId;

  if (searchMaestro.results.length > 0) {
    dealMaestroId = searchMaestro.results[0].id;
  } else {
    const nuevoMaestro = await hubspotClient.crm.deals.basicApi.create({
      properties: {
        dealname:       [nroExpediente, nombreInquilino, 'Expediente Consolidado'].filter(Boolean).join(' — '),
        pipeline:       '3920555199',
        dealstage:      '5598176486',   // En recupero (pipeline maestro)
        nro_expediente: String(nroExpediente)
      }
    });
    dealMaestroId = nuevoMaestro.id;
  }

  // Asociar deal de período → deal maestro (Deal-Deal HUBSPOT_DEFINED = 5)
  await hubspotClient.crm.associations.v4.basicApi.create(
    'deals', dealPeriodoId, 'deals', dealMaestroId,
    [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 5 }]
  );

  return callback({
    outputFields: {
      resultado: `CREADO — período ${dealPeriodoId} → maestro ${dealMaestroId} | total: $${fmt(totalTicket)}`
    }
  });
};

// ── Helpers ────────────────────────────────────────────────────────────────

function fmt(n) {
  return Number(n).toLocaleString('es-AR', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
}

async function crearNota(client, texto, dealId, assocTypeId) {
  await client.crm.objects.notes.basicApi.create({
    properties: {
      hs_note_body:  texto,
      hs_timestamp:  String(Date.now())
    },
    associations: [{
      to:    { id: dealId },
      types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: assocTypeId }]
    }]
  });
}
